<?php require __DIR__.'/../includes/app.php';need('System Administrator','Business Manager','Rental Officer');ensure_agreement_signature_schema();head('Rental agreements');
$agreements=q("SELECT a.*,r.reservation_code,c.first_name,c.last_name,v.make,v.model,v.registration_no FROM rental_agreements a JOIN reservations r USING(reservation_id) JOIN customers c ON c.customer_id=a.customer_id JOIN vehicles v ON v.vehicle_id=a.vehicle_id ORDER BY a.agreement_id DESC")->fetchAll();?>
<div class="card"><div class="card-header d-flex align-items-center justify-content-between"><span>Rental agreements</span><span class="small text-muted"><?=count($agreements)?> total</span></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle">
<thead><tr><th scope="col">Agreement</th><th scope="col">Reservation</th><th scope="col">Customer</th><th scope="col">Vehicle</th><th scope="col">Deposit</th><th scope="col">Renter signature</th><th scope="col">Staff signature</th><th scope="col">Status</th><th scope="col">Action</th></tr></thead><tbody>
<?php foreach($agreements as $a):$renterSigned=!empty($a['renter_signed_at']);$staffSigned=!empty($a['staff_signed_at']);?>
<tr><td><strong><?=e($a['agreement_number'])?></strong></td><td><?=e($a['reservation_code'])?></td><td><?=e($a['first_name'].' '.$a['last_name'])?></td><td><?=e($a['make'].' '.$a['model'].' · '.$a['registration_no'])?></td><td><?=money($a['security_deposit'])?></td>
<td><?=$renterSigned?'<span class="signature-state done"><i class="bi bi-check-circle-fill"></i> Signed</span><small class="d-block text-muted">'.e($a['renter_signed_at']).'</small>':'<span class="signature-state waiting"><i class="bi bi-hourglass-split"></i> Waiting</span>'?></td>
<td><?=$staffSigned?'<span class="signature-state done"><i class="bi bi-check-circle-fill"></i> Signed</span><small class="d-block text-muted">'.e($a['staff_signed_at']).'</small>':'<span class="signature-state waiting"><i class="bi bi-hourglass-split"></i> Waiting</span>'?></td>
<td><?=badge($a['status'])?></td><td class="text-nowrap"><a class="btn btn-sm <?=$renterSigned&&!$staffSigned?'btn-accent':'btn-outline-primary'?>" href="<?=BASE?>shared/agreement.php?id=<?=$a['agreement_id']?><?=$renterSigned&&!$staffSigned?'&amp;step=4':''?>"><?=$renterSigned&&!$staffSigned?'Review & countersign':'Open agreement'?></a><?php if($renterSigned&&$staffSigned):?> <a class="btn btn-sm btn-outline-secondary" href="<?=BASE?>shared/agreement_download.php?id=<?=$a['agreement_id']?>"><i class="bi bi-download"></i><span class="visually-hidden">Download signed agreement</span></a><?php endif;?></td></tr>
<?php endforeach;?><?php if(!$agreements):?><tr><td colspan="9" class="text-center text-muted py-4">No rental agreements yet.</td></tr><?php endif;?></tbody></table></div></div></div><?php foot();
